   880
   881          switch (e->tag) {
   882          case EXIF_TAG_USER_COMMENT:
   883
   884                  /*
   885                   * The specification says UNDEFINED, but some
   886                   * manufacturers don't care and use ASCII. If this is the
   887                   * case here, only refuse to read it if there is no chance
   888                   * of finding readable data.
   889                   */
   890                  if ((e->format != EXIF_FORMAT_ASCII) ||
   891                      (e->size <= 8) ||
   892                      ( memcmp (e->data, "ASCII\0\0\0"  , 8) &&
   893                        memcmp (e->data, "UNICODE\0"    , 8) &&
   894                        memcmp (e->data, "JIS\0\0\0\0\0", 8) &&
   895                        memcmp (e->data, "\0\0\0\0\0\0\0\0", 8)))
   896                          CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
   897
   898                  /*
   899                   * Note that, according to the specification (V2.1, p 40),
   900                   * the user comment field does not have to be
   901                   * NULL terminated.
   902                   */
   903                  if ((e->size >= 8) && !memcmp (e->data, "ASCII\0\0\0", 8)) {
   904                          strncpy (val, (char *) e->data + 8, MIN (e->size - 8, maxlen-1));
   905                          break;
   906                  }
   907                  if ((e->size >= 8) && !memcmp (e->data, "UNICODE\0", 8)) {
   908                          strncpy (val, _("Unsupported UNICODE string"), maxlen-1);
   909                  /* FIXME: use iconv to convert into the locale encoding.
   910                   * EXIF 2.2 implies (but does not say) that this encoding is
   911                   * UCS-2.
   912                   */
   913                          break;
   914                  }
   915                  if ((e->size >= 8) && !memcmp (e->data, "JIS\0\0\0\0\0", 8)) {
   916                          strncpy (val, _("Unsupported JIS string"), maxlen-1);
   917                  /* FIXME: use iconv to convert into the locale encoding */
   918                          break;
   919                  }
   920
   921                  /* Check if there is really some information in the tag. */
   922                  for (i = 0; (i < e->size) &&
   923                              (!e->data[i] || (e->data[i] == ' ')); i++);
   924                  if (i == e->size) break;
   925
   926                  /*
   927                   * If we reach this point, the tag does not
   928                   * comply with the standard but seems to contain data.
   929                   * Print as much as possible.
   930                   * Note: make sure we do not overwrite the final \0 at maxlen-1
   931                   */
   932                  exif_entry_log (e, EXIF_LOG_CODE_DEBUG,
   933                          _("Tag UserComment contains data but is "
   934                            "against specification."));
   935                  for (j = 0; (i < e->size) && (j < maxlen-1); i++, j++) {
   936                          exif_entry_log (e, EXIF_LOG_CODE_DEBUG,
   937                                  _("Byte at position %i: 0x%02x"), i, e->data[i]);
   938                          val[j] = isprint (e->data[i]) ? e->data[i] : '.';
   939                  }
   940                  break;
   941
   942          case EXIF_TAG_EXIF_VERSION:
   943                  CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
   944                  CC (e, 4, val, maxlen);
   945                  strncpy (val, _("Unknown Exif Version"), maxlen-1);
   946                  for (i = 0; *versions[i].label; i++) {
   947                          if (!memcmp (e->data, versions[i].label, 4)) {
   948                                  snprintf (val, maxlen,
   949                                          _("Exif Version %d.%d"),
   950                                          versions[i].major,
   951                                          versions[i].minor);
   952                                  break;
   953                          }
   954                  }
   955                  break;
   956          case EXIF_TAG_FLASH_PIX_VERSION:
   957                  CF (e, EXIF_FORMAT_UNDEFINED, val, maxlen);
   958                  CC (e, 4, val, maxlen);
   959                  if (!memcmp (e->data, "0100", 4))
   960                          strncpy (val, _("FlashPix Version 1.0"), maxlen-1);
